import mediaMap from '@/data/mediaMap.json'

/**
 * Resolve a bundled photograph to its CDN copy.
 *
 * Some photographs are layout rather than content — page hero images, the
 * lighting strip, the services feature card. They belong in the code because
 * the design chooses them, but there is no reason to serve them from the
 * container when the same file sits on the CDN in a better format.
 *
 * The map is generated by `backend/app/scripts/migrate_media.py`, which is
 * also what does the uploading, so the two cannot drift. An unmapped path
 * falls through to the local file, which still ships in the build — so this
 * degrades to exactly the previous behaviour rather than to a broken image.
 */
export const photo = (path) => mediaMap[path] ?? path
